class ObfuscatedTO {
  readonly id: string;
  #plain = new Map<string, string>();
  #protected = new Map<string, string>();
  #sealed?: { iv: Uint8Array; tag: Uint8Array; data: Uint8Array };
  seal(key: Uint8Array): void {
    const iv = randomBytes(12);
    const c = createCipheriv('aes-256-gcm', key, iv);
    const data = Buffer.concat([c.update(JSON.stringify([...this.#protected])), c.final()]);
    this.#sealed = { iv, tag: c.getAuthTag(), data };
    this.#protected.clear();                   // drop the plaintext copy
  }
  toJSON(): { id: string } { return { id: this.id }; }   // plaintext never leaves the object
}
